ESCCommManager::ESCCommManager(USBD_NODE_ID node_id, SUsbDescriptors * descs ) : CUsbCommBase( descs, node_id ), nodeId_( node_id ) 
{

	this->prKind_ = EscPrinter;
	this->myPrinterType_ = FirstPrinter;

	pConfig_ = Configuration::getInstance();

	pMyNumeric_ = NULL;
	pMyMarquee_ = NULL;
	pMyPrinterMgr_ = NULL;
	pMyWeigher_ = NULL;

	numericRequestedStatus_ = false;
	marqueeRequestedStatus_ = false;

	pBulkData_ = NULL;
	sendingBulkData_ = false;
	bulkDataLength_ = 0;

	xmitting_ = false;
	recvdESCMessage_ = false;

	intXferTimeOut_ = pConfig_->getInterruptXferTimeout();
	bulkXferTimeOut_ = pConfig_->getBulkXferTimeout();

	registerEvent(System, SysReset);

	createPipes();

#ifdef USE_ACCOUNTANT
	if (dataType == 0)
		dataType = util_acc::registerDataType(dataTypeName);

	util_acc::addInstance(dataType);
#endif
}

ESCCommManager::~ESCCommManager()
{
	UsbRemoveComponent removeMe(nodeId_, this);
	dispatchEvent(&removeMe);

	//shutdown the msg thread
	ShutdownNicely();

	deregisterAllEvents();

	if (pMyNumeric_)
	{
		delete pMyNumeric_;
		pMyNumeric_ = NULL;
	}

	if (pMyMarquee_)
	{
		delete pMyMarquee_;
		pMyMarquee_ = NULL;
	}

	if (pMyPrinterMgr_)
	{
		delete pMyPrinterMgr_;
		pMyPrinterMgr_ = NULL;
	}

#ifdef USE_ACCOUNTANT
	util_acc::removeInstance(dataType);
#endif
}

