void ESCCommManager::processEvent( Util::CSmartPtr< EvolMessageWrapper> & msg )
{

	usbEvolHdr_.setSourcePhysicalAddress(0x00);
	usbEvolHdr_.setSourceLogicalAddress(USBEvolHeader::USER_INTERFACE);

	switch (msg->getDeviceType())
	{
		case System				:	handleSysEvent((SysEvent) msg->getEventType(), msg->Data() );
									break;
		case Numeric			:	handleNumericEvent((NmEvent) msg->getEventType(), msg->Data());
									break;
		case NumericSystem		:	handleNumericSystemEvent((NmEvent) msg->getEventType(), msg->Data());
									break;
		case Marquee			:	handleMarqueeEvent((MqEvent) msg->getEventType(), msg->Data());
									break;
		case MarqueeSystem		:	handleMarqueeSystemEvent((MqEvent) msg->getEventType(), msg->Data());
									break;
		case Printer			:	handlePrinterEvent((PrEvent) msg->getEventType(), msg->Data());
									break;
		case PrinterSystem		:	handlePrinterSysEvent((SysEvent) msg->getEventType(), msg->Data());
							 		break;
		//copy from WeigherCommmanager
		case Weigher			:	handleWeigherEvent( (WgEvent) msg->getEventType(), msg->Data() );
									break;
		case WeigherSystem		:	 handleWeigherSysEvent( (SysEvent) msg->getEventType(), msg->Data() );
									break;

		default					:
									break;
	}

		

}

bool ESCCommManager::handleNumericSystemEvent(NmEvent nmEvent, const char * UNUSED(recvBuffer))
{
	UNREFERENCED_PARAMETER(recvBuffer);
		
	char str[255];
	DWORD result = OK;
	bool is_custom_code = false;


	switch (nmEvent)
	{
		/*messages sent out to usb device*/
		case NmSysReqStatus:		
		{
			Debug::trace("ESCCommManager.System.Message.Out", "SysReqStatus");	

			numericRequestedStatus_ = true;

			SysGenericMsg genMsg;
			memset((char *) &genMsg, 0, sizeof(genMsg));

			genMsg.function_code = SysStatus;

			usbEvolHdr_.setDestinationLogicalAddress(USBEvolHeader::SYSTEM);
			usbEvolHdr_.setMessageLength(sizeof(genMsg));
			usbEvolHdr_.Serialize( str );

			memcpy( &str[10], (char *) &genMsg, sizeof(genMsg));
			sendUsbInterruptMessage( ( const char * ) str,  sizeof(genMsg) + 10, result, is_custom_code );
			
		}
		break;

		default:
		{
			Debug::trace("ESCCommManager.Error", HobString("Some Other Sytem Event: ") +
												 HobString(Integer::toString((UINT16) nmEvent)));
		}
		break;

	}

	if ( result != OK ) //error
	{
		printUSBError( result, is_custom_code );
	}

	return true;

}


