void ESCCommManager::processUsbMessage( std::string & msg, CUsbPipe::EvolPipeType UNUSED(pipe_type) )
{
	UNREFERENCED_PARAMETER(pipe_type);
		
	const char * ptr = msg.c_str();
	USBEvolHeader usbEvolHeader( ptr, true);

	UINT16 physicalAddress = usbEvolHeader.getSourcePhysicalAddress();
	UINT16 logicalAddress = usbEvolHeader.getSourceLogicalAddress();

//jrb
	if (physicalAddress > 0)
		gPhysicalAddress = true;
	else
		gPhysicalAddress = false;

	ptr += 10;

	if (logicalAddress == USBEvolHeader::ESC_NUMERIC)
	{
		receivedNumericMessage((NmGenericMsg *) ptr, physicalAddress); 
	}
	else if (logicalAddress == USBEvolHeader::ESC_MARQUEE)
	{
		receivedMarqueeMessage((MqGenericMsg *) ptr, physicalAddress); 
	}
	else if (logicalAddress == USBEvolHeader::SYSTEM)
	{
		if ( physicalAddress == 0x5555 )
			receivedWeigherSysMessage((SysGenericMsg *) ptr);
		else //if ( 1 /*lcg rev 0.2 need to change physicalAddress == 0x???*/ )
			receivedPrinterSysMessage((SysGenericMsg *) ptr, physicalAddress);
	
	} 
	else if (logicalAddress == USBEvolHeader::EVOL_PRINTER)
	{
		receivedPrinterDevMessage((PrGenericMsg *) ptr, physicalAddress, logicalAddress);
	}
	else if (logicalAddress == USBEvolHeader::WEIGHER)
	{
		receivedWeigherDevMessage((UltimaWgGeneric *) ptr, physicalAddress);
	}
}

void ESCCommManager::receivedNumericMessage(NmGenericMsg *genMsg, UINT16 physicalAddress) 
{
	switch (genMsg->nmEvent)
	{
		case NmWakeup:{	
							Debug::trace("ESCCommManager.Numeric.Message.In", "NmWakeup");	

							if (pMyNumeric_ == NULL)
							{
								Debug::trace("ESCCommManager.Numeric.Message.In", "************************************************");

						   		// Create a new thread
								pMyNumeric_ = RealTimeController::getInstance()->NewUSBNumeric(nodeId_, this, physicalAddress, NmUsbEvol);

								usbEvolHdr_.setDestinationPhysicalAddress(physicalAddress);
							}
							else
							{

								NmWakeupMsg *nmWakeupMsg = (NmWakeupMsg *) genMsg;

							 	NumericWakeup nmwu(nmWakeupMsg, this);

								const char *pNmwuMsg = nmwu.serialize();
								int mLength = nmwu.getSerializedLength();

								pMyNumeric_->send(pNmwuMsg, mLength);
							}
						}
						break;
		case NmInquire:	{
							Debug::trace("ESCCommManager.Numeric.Message.In", "NmInquire");	
							NmInquireMsg *nmInquireMsg = (NmInquireMsg *) genMsg;

							NumericInquire nmi(nmInquireMsg, this);

							const char *pnmInquire = nmi.serialize();
							int mLength = nmi.getSerializedLength();

							pMyNumeric_->send(pnmInquire, mLength);
						}
						break;
		default:
						Debug::trace("ESCCommManager.Error", HobString("Received Unknown Numeric message type: 0x") +
																 HobString(Hex::toString(genMsg->nmEvent)));
						break;
	}

}

